/**
 * Writes the client's agent plugin generated by ABAP (agent factory) into clients/<slug>/plugin
 * and registers it in .claude-plugin/marketplace.json.
 * Usage: npm run plugin:pull -w @clients/<slug>   (or: node tools/pull-plugin.mjs <slug>)
 * Env:   ABAP_API_TOKEN or ABAP_TOKEN (or a git-ignored .abap-token at the repository root), ABAP_URL (default: production)
 * Read-only on ABAP. Generate or update the agent in the app (Agente) or with the MCP tool abap_generate_client_agent.
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { planPlugin, registerInMarketplace } from "./lib-plugin.mjs";
import { CLIENTS, ROOT } from "./lib.mjs";

const slug = process.argv[2];
if (!slug) {
  console.error("usage: node tools/pull-plugin.mjs <client-slug>");
  process.exit(1);
}
const clientDir = join(CLIENTS, slug);
if (!existsSync(join(clientDir, "client.json"))) throw new Error(`unknown client: ${slug}`);
const client = JSON.parse(readFileSync(join(clientDir, "client.json"), "utf8"));

const base = (process.env.ABAP_URL ?? "https://governance-system.contato-adulto-tdah.workers.dev").replace(/\/$/, "");
const tokenFile = join(ROOT, ".abap-token");
const token = process.env.ABAP_API_TOKEN ?? process.env.ABAP_TOKEN ?? (existsSync(tokenFile) ? readFileSync(tokenFile, "utf8").trim() : "");
if (!token) throw new Error("ABAP_API_TOKEN not set (env var or .abap-token at the repository root)");

const res = await fetch(`${base}/api/v1/projects/${encodeURIComponent(client.projectId)}/agent`, { headers: { authorization: `Bearer ${token}` } });
const body = await res.json().catch(() => ({}));
if (!res.ok) throw new Error(`ABAP ${res.status}: ${body.error ?? ""} ${body.message ?? ""}`.trim());

const out = join(clientDir, "plugin");
const manifestPath = join(out, "_abap.json");
const previous = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, "utf8")) : { files: [] };
const { writes, deletes, manifest, errors } = planPlugin(body.agent, slug, previous);
if (errors.length) {
  console.error(errors.map((e) => `✗ ${e}`).join("\n"));
  process.exit(1);
}
const inside = (rel) => {
  const p = resolve(out, rel);
  if (!p.startsWith(resolve(out) + "/")) throw new Error(`refusing to write outside plugin/: ${rel}`);
  return p;
};
for (const rel of deletes) rmSync(inside(rel), { force: true });
for (const w of writes) {
  const p = inside(w.path);
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, w.content);
}
writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");

const marketPath = join(ROOT, ".claude-plugin", "marketplace.json");
const market = JSON.parse(readFileSync(marketPath, "utf8"));
const description = JSON.parse(writes.find((w) => w.path === ".claude-plugin/plugin.json").content).description;
writeFileSync(marketPath, JSON.stringify(registerInMarketplace(market, slug, body.agent, description), null, 2) + "\n");

console.log(`${slug}: ${body.agent.name} v${body.agent.version} — ${writes.length} files written, ${deletes.length} removed, marketplace updated`);
